import{_ as l,r as a,o,c as p,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Partial Column - October CMS - 3.x","titleTemplate":false,"description":"List Column","frontmatter":{"subtitle":"List Column","shortname":"Partial"},"headers":[{"level":2,"title":"Using View Templates","slug":"using-view-templates","link":"#using-view-templates","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"3.x/element/lists/column-partial.md","filePath":"3.x/element/lists/column-partial.md"}'),r={name:"3.x/element/lists/column-partial.md"};function u(d,e,h,m,k,g){const n=a("pre-heading"),t=a("post-heading");return o(),p("div",null,[s(n),e[0]||(e[0]=c("h1",null,"Partial Column",-1)),s(t),e[1]||(e[1]=i(`<p>The <code>partial</code> column will render the column content using a partial or view file. The <code>path</code> value can refer to a partial view file otherwise the column name is used as the partial name. The default scope for the view path is the controller&#39;s view path.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Content
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> content_column
</code></pre></div><p>The following properties are supported.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>path</strong></td><td>path to a <a href="./../../extend/system/views.html">partial view file</a> or <a href="./../../extend/services/response-view.html">view template code</a>, defaults to the column name with <strong>column_</strong> as a prefix.</td></tr></tbody></table></div><p>When the <code>path</code> is set to an unqualified file name (a file name without a directory path and extension), the source path is determined to be in the model or controller directories. The following example will check for the partial file at <strong>../models/mymodel/_column_for_content.php</strong> or <strong>../controllers/mycontroller/_column_for_content.php</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> column_for_content
</code></pre></div><p>You may specify a fully qualified <code>path</code> to access partials outside the model or controller directories. This can be useful for sharing partials between definitions.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Content
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> $/acme/blog/partials/_content_column.php
</code></pre></div><p>Inside the partial these variables are available.</p><ul><li><code>$value</code> is the default cell value</li><li><code>$record</code> is the model used for the cell</li><li><code>$column</code> is the configured class object <code>Backend\\Classes\\ListColumn</code></li></ul><p>Here is an some example contents of the <strong>_content_column.php</strong> file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">is_active</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token function">e</span><span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="using-view-templates"><a href="#using-view-templates" class="header-anchor">#</a> Using View Templates</h2><p>You may pass a view template code as the <code>path</code> to access view service templates inside the plugin. The following code would be found at the path <strong>plugins/acme/blog/views/listcolumns/content.php</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Content
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> acme.blog<span class="token punctuation">:</span><span class="token punctuation">:</span>listcolumns.content
</code></pre></div><div class="custom-block tip"><p>The path must contain the <code>::</code> characters to activate the view service.</p></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../extend/system/views.html">Rendering Controller Views</a></li><li><a href="./../../extend/services/response-view.html">Response &amp; View Service</a></li></ul></div>`,18))])}const y=l(r,[["render",u]]);export{f as __pageData,y as default};
